import{_ as t,o as a,c as n,a3 as d}from"./chunks/framework.BlfGB29P.js";const m=JSON.parse('{"title":"Attendance — Developer Guide","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Attendance — Developer Guide | EloSync Docs"}],["meta",{"property":"og:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"property":"og:url","content":"https://docs.elosync.com/developer-guide/attendance"}],["meta",{"property":"og:image","content":"https://docs.elosync.com/og-image.svg"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Attendance — Developer Guide | EloSync Docs"}],["meta",{"name":"twitter:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"name":"twitter:image","content":"https://docs.elosync.com/og-image.svg"}],["link",{"rel":"canonical","href":"https://docs.elosync.com/developer-guide/attendance"}]]},"headers":[],"relativePath":"developer-guide/attendance.md","filePath":"developer-guide/attendance.md","lastUpdated":1786226971000}'),o={name:"developer-guide/attendance.md"};function c(i,e,s,r,l,p){return a(),n("div",null,[...e[0]||(e[0]=[d('<h1 id="attendance-—-developer-guide" tabindex="-1">Attendance — Developer Guide <a class="header-anchor" href="#attendance-—-developer-guide" aria-label="Permalink to &quot;Attendance — Developer Guide&quot;">​</a></h1><p>Slug <code>attendance</code>, middleware <code>module:attendance</code>, permissions <code>attendance.*</code>. Hard-depends on <code>employees</code>.</p><h2 id="domain" tabindex="-1">Domain <a class="header-anchor" href="#domain" aria-label="Permalink to &quot;Domain&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Model</th><th>Table</th><th>Notes</th></tr></thead><tbody><tr><td><code>AttendanceRecord</code></td><td><code>attendance_records</code></td><td>Unique <code>(tenant_id, employee_id, date)</code>; soft deletes</td></tr></tbody></table><p>Enum: <code>AttendanceStatusEnum</code> — <code>present</code> | <code>absent</code> | <code>half_day</code> | <code>remote</code> | <code>late</code>.</p><p>Service: <code>AttendanceRecordService</code> (CRUD + stats + <code>markLoginCheckIn</code> + self-service ownership constraints). Spatie log name <code>attendance</code>.</p><p><strong>Ownership:</strong> Staff with <code>attendance.create</code> / <code>attendance.update</code> may only create/update records for their linked active employee; list/show are scoped to self. Staff creates force <code>present</code> and may only update check-out/notes afterward (no status or check-in rewrite). Admin/manager/superadmin (<code>AttendanceRecordPolicy::canManageOthers</code>) may mark and edit any employee (including correcting check-in/out times, status, and notes). Login auto check-in is unchanged.</p><p>Tenant settings (<code>attendance</code> group): <code>office_start_time</code>, <code>office_end_time</code>, <code>attendance_grace_minutes</code>, <code>work_week_days</code>. Those <code>H:i</code> values are workspace-local wall clocks; “today”, check-in time, and late classification use <code>Settings → General → Timezone</code> via <code>Carbon::now($workspaceTimezone)</code> in <code>AttendanceRecordService::markLoginCheckIn</code> (same convention as reminders/meetings — see <a href="/developer-guide/tenant-settings#timezone-and-scheduled-datetimes">Workspace timezone convention</a>). Login check-in runs from <code>LoginController</code> when the module is installed and the user has an active linked employee. Location columns: <code>check_in_ip</code>, <code>check_in_latitude</code>, <code>check_in_longitude</code> (and check-out equivalents).</p><h2 id="backend-layout" tabindex="-1">Backend layout <a class="header-anchor" href="#backend-layout" aria-label="Permalink to &quot;Backend layout&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Piece</th><th>Path</th></tr></thead><tbody><tr><td>Model</td><td><code>app/Models/AttendanceRecord.php</code></td></tr><tr><td>Service</td><td><code>app/Services/Tenant/AttendanceRecordService.php</code></td></tr><tr><td>Controller</td><td><code>app/Http/Controllers/Tenant/Api/V1/AttendanceRecordController.php</code></td></tr><tr><td>Requests</td><td><code>app/Http/Requests/Tenant/Api/V1/AttendanceRecord/*</code></td></tr><tr><td>Tests</td><td><code>tests/Feature/Tenant/Attendance/</code></td></tr></tbody></table><h2 id="permissions" tabindex="-1">Permissions <a class="header-anchor" href="#permissions" aria-label="Permalink to &quot;Permissions&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>attendance.view | create | update | delete | restore | force.delete</span></span></code></pre></div><p>Default <strong>staff</strong> role includes <code>attendance.view</code>, <code>attendance.create</code>, and <code>attendance.update</code> (self-service). Existing workspaces receive the create/update grants via additive <code>TenantPermissionSynchronizer</code> migration.</p><h2 id="api" tabindex="-1">API <a class="header-anchor" href="#api" aria-label="Permalink to &quot;API&quot;">​</a></h2><p>See <a href="/api/tenant-v1-attendance">tenant-v1-attendance.md</a>.</p><h2 id="frontend" tabindex="-1">Frontend <a class="header-anchor" href="#frontend" aria-label="Permalink to &quot;Frontend&quot;">​</a></h2><ul><li>API client: <code>attendanceRecordService</code> in <code>src/api/services.ts</code></li><li>Keys / permissions: <code>QUERY_KEYS.attendance*</code>, <code>PERMISSIONS.attendance</code></li><li>Nav under <strong>HR</strong> (module <code>attendance</code>)</li></ul><h2 id="tests" tabindex="-1">Tests <a class="header-anchor" href="#tests" aria-label="Permalink to &quot;Tests&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> artisan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --compact</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tests/Feature/Tenant/Attendance</span></span></code></pre></div>',19)])])}const u=t(o,[["render",c]]);export{m as __pageData,u as default};
